                Id = c.Id,
                Name = c.Name,
                Subcategories = c.Subcategories
                    .Select(s => new SubcategoryDto { Id = s.Id, Name = s.Name })
                    .ToList()
            })
            .ToList();

        return Ok(response);
    }
}

