export interface ProductSummary {
  id: string;
  name: string;
}

export interface ProductListResponse {
  items: ProductSummary[];
  page: number;
  pageSize: number;
  totalCount: number;
}

export interface SubcategorySummary {
  id: string;
  name: string;
}

export interface CategorySummary {
  id: string;
  name: string;
  subcategories: SubcategorySummary[];
}
---API---
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

import { ApiClient } from '../../core/api-client';
import { CategorySummary, ProductListResponse } from './product.model';

@Injectable({ providedIn: 'root' })
export class CatalogApiService {
  private apiClient = inject(ApiClient);

  getProducts(
    page: number,
    categoryId?: string | null,
    subcategoryId?: string | null,
    sortBy?: string | null,
    sortDirection?: string | null,
    search?: string | null
  ): Observable<ProductListResponse> {
    const params: Record<string, string | number> = { page };
    if (subcategoryId) {
      params['subcategoryId'] = subcategoryId;
    } else if (categoryId) {
      params['categoryId'] = categoryId;
    }
    if (sortBy) {
      params['sortBy'] = sortBy;
    }
    if (sortDirection) {
      params['sortDirection'] = sortDirection;
    }
    if (search) {
      params['search'] = search;
    }
    return this.apiClient.get<ProductListResponse>('/products', params);
  }

  getCategories(): Observable<CategorySummary[]> {
    return this.apiClient.get<CategorySummary[]>('/categories');
  }
}

