      undefined,
      undefined,
      'Kaffee'
    );
    fixture.detectChanges();

    const buttons = element.querySelectorAll('button');
    const nextButton = Array.from(buttons).find((b) => b.textContent?.includes('Weiter')) as HTMLButtonElement;
    nextButton.click();

    expectProductsRequest(
      httpMock,
      2,
